#pragma once

#include <stddef.h>
#include <stdint.h>

#include "src/actuator/calibration_end_detector.h"

// Robot end-current replays for test_calibration_end_detector.cpp. Data only,
// generated by the review-fix reference (ced-fix/gen_fixture.py and detector.py,
// the design stage's detector.py plus the 2026-11-24 review fixes) from front-leg
// jogs on a stand logged 2026-11-24. One sample per telemetry frame (about
// 51.5 ms) from the first nonzero PWM to the host's stop. Per sample: e = drive
// edges since the drive started, i = the frame's current field x 10 (tenths of an
// IS count; the telemetry truncates to whole counts), r = 1 once the PWM reached
// the move PWM. Groups:
//   endcur: the scripted end-current jogs at PWM 80/120/150 (firmware
//           hallcal-1123; endcur-111808 = FL leg, endcur-112315 = FR leg), each up
//           to the design reference's decision (the design goldens).
//   today:  every jog of the PWM 128/150 runs that followed (clearance-FL/FR,
//           fr-recover, hipend-FL, rodscale-*), among them the FRHL curl at 128
//           that stalled 878 edges short of its switch (clearance-FR-115750#7).
//   short:  real curl-end approaches started later in the same approach (the
//           drive begins that many full-PWM samples in, its ramp kept), each from
//           the middle of the band the design reference called stuck, and the
//           FRHL stall started 5 samples later.
// The expected verdict and its sample k are the reference's; kind None: the
// host stopped the move first.

struct RobotEndSample
{
    int16_t e;
    uint16_t i;
    uint8_t r;
};

enum class RobotEndGroup : uint8_t
{
    EndCurrent,  // endcur: the scripted end-current jogs
    Today,       // the PWM 128/150 runs
    Short,       // real end approaches started later
};

struct RobotEndMove
{
    const char *name;   // log#move index
    RobotEndGroup group;
    const char *joint;
    int pwm;
    bool retract;       // -PWM: the rod retracts
    bool curl;
    CalibrationEnd expected;
    int k;              // sample index of the expected decision (-1: none)
    int edges;          // drive edges at the decision
    const RobotEndSample *samples;
    size_t count;
};

